// SUP-05: client-side mirror of servicio_back/src/domain/work-orders/tracking-code.ts
// (normalization only; codes are generated by the backend).
export const TRACKING_CODE_PATTERN = /^[ABCDEFGHJKMNPQRSTUVWXYZ23456789]{8}$/;

export function normalizeTrackingCode(raw: string): string {
  return raw.replace(/[\s-]/g, '').toUpperCase();
}

export function parseWorkOrderNumber(raw: string): number {
  const digits = raw.trim().toUpperCase().replace(/^OT-?/, '');
  return /^\d{1,10}$/.test(digits) ? Number(digits) : Number.NaN;
}

export function formatWorkOrderNumber(number: number): string {
  return `OT-${String(number).padStart(6, '0')}`;
}
